_LEVELS = frozenset(("INFO", "WARN", "ERROR"))


def parse_log_line(s):
    if not isinstance(s, str):
        raise TypeError(f"s must be str, got {type(s).__name__}")

    stripped = s.strip()
    if not stripped:
        raise ValueError("empty line")

    parts = stripped.split(None, 2)
    if len(parts) < 3:
        raise ValueError(f"expected 'TIMESTAMP LEVEL MSG', got {s!r}")

    timestamp, level, msg = parts

    if level not in _LEVELS:
        raise ValueError(f"invalid level {level!r}")

    if not msg.strip():
        raise ValueError("empty msg")

    candidate = timestamp[:-1] + "+00:00" if timestamp.endswith("Z") else timestamp
    try:
        datetime.fromisoformat(candidate)
    except ValueError:
        raise ValueError(f"invalid ISO8601 timestamp {timestamp!r}") from None

    return (timestamp, level, msg)
